import numpy as np

class GSLMatrix(ctypes.Structure):
    pass

gsl.gsl_matrix_alloc.argtypes = [ctypes.c_int, ctypes.c_int]
gsl.gsl_matrix_alloc.restype = GSLMatrix

gsl.gsl_matrix_free.argtypes = [GSLMatrix]

def numpy_to_gsl_matrix(np_array):
    matrix = gsl.gsl_matrix_alloc(np_array.shape[0], np_array.shape[1])
    for i in range(np_array.shape[0]):
        for j in range(np_array.shape[1]):
            gsl.gsl_matrix_set(matrix, i, j, np_array[i, j])
    return matrix

def gsl_matrix_to_numpy(gsl_matrix):
    rows, cols = gsl.gsl_matrix_size(gsl_matrix)
    np_array = np.zeros((rows, cols))
    for i in range(rows):
        for j in range(cols):
            np_array[i, j] = gsl.gsl_matrix_get(gsl_matrix, i, j)
    return np_array

gsl.gsl_multifit_covar.argtypes = [GSLMatrix, ctypes.c_double]
gsl.gsl_multifit_covar.restype = GSLMatrix

def compute_covariance_matrix(jacobian, epsrel, dimensions):
    if dimensions <= 0:
        raise ValueError("Dimensions must be positive.")

    gsl_jacobian = numpy_to_gsl_matrix(jacobian)
    covariance_matrix = gsl.gsl_multifit_covar(gsl_jacobian, epsrel)
    return gsl_matrix_to_numpy(covariance_matrix)

