def create_gsl_matrix(matrix):
    m = len(matrix)
    gsl_matrix_t = gsl.gsl_matrix_alloc(m, m)
    for i in range(m):
        for j in range(m):
            gsl.gsl_matrix_set(gsl_matrix_t, i, j, matrix[i][j])
    return gsl_matrix_t

def create_gsl_vector_complex(size):
