    """Computes x * (2^e) using the GNU Scientific Library (GSL)."""
    if x == 0.0:
        return 0.0
    if e == 0:
        return x
    if e > 1023:
        return float('inf')
    if e < -1022:
        return 0.0
    return gsl.gsl_ldexp(x, e)

