#include <gsl/gsl_halton.h>

int main()
{

    // Load GSL libraries
    auto gsl_cblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL);
    auto gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so");

    // Get dimension from user
    int dimension = int(input("Enter dimension (1-1229): "));

    // Validate dimension
    if (dimension < 1 || dimension > 1229) {
        print("Invalid dimension.");
        return 1;
    }

    // Initialize Halton quasi-random number generator
    gsl_Halton_state *state;
    gsl_Halton_init(dimension, &state);

    // Generate Halton point
    double point[dimension];
    gsl_Halton_point(state, point);

    // Print Halton point
    for (int i = 0; i < dimension; i++) {
        print(point[i]);
    }

    // Clean up
    gsl_Halton_free(&state);

    return 0;
}

