class GSLMatrix:
    def __init__(self, rows, cols):
        self.rows = rows
        self.cols = cols
        self._allocate()

    def _allocate(self):
        gsl.gsl_matrix_alloc(self.rows, self.cols)

    def free(self):
        gsl.gsl_matrix_free(self)

    def to_numpy(self):
        return np.array(gsl.gsl_matrix_data(self)).reshape(self.rows, self.cols)

