import ctypes

class GSLMatrix:
    def __init__(self, data):
        self.gsl_matrix = gsl.gsl_matrix_alloc(len(data), len(data[0]))
        for i in range(len(data)):
            for j in range(len(data[0])):
                gsl.gsl_matrix_set(self.gsl_matrix, i, j, data[i][j])

    def retrieve(self):
        data = []
        for i in range(gsl.gsl_matrix_rows(self.gsl_matrix)):
            row = []
            for j in range(gsl.gsl_matrix_cols(self.gsl_matrix)):
                row.append(gsl.gsl_matrix_get(self.gsl_matrix, i, j))    
            data.append(row)

        return data

    def __del__(self):
        gsl.gsl_matrix_free(self.gsl_matrix)


