def compute_integral(py_func, a, b, epsabs, epsrel, n):
    func = gsl_function()
    func.f = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double, ctypes.POINTER(ctypes.c_double))(func_wrapper)

    workspace = gsl.gsl_integration_romberg_alloc(func, a, b, epsabs, epsrel, n)
    result = gsl.gsl_integration_romberg(func, a, b, epsabs, epsrel, n, workspace)

    gsl.gsl_integration_romberg_free(workspace)

    return result.integral, result.neval

def func_wrapper(x, params):
    return py_func(x[0])

