import ctypes

class GSL_Histogram2D(ctypes.Structure):
    pass

gsl.gsl_histogram2d_calloc_range.restype = ctypes.POINTER(GSL_Histogram2D)
gsl.gsl_histogram2d_calloc_range.argtypes = [ctypes.c_int, ctypes.c_int,
                                    ctypes.POINTER(ctypes.c_double),
                                    ctypes.POINTER(ctypes.c_double)]

def create_histogram2d(nx, ny, xrange, yrange):
    if not isinstance(nx, int) or nx <= 0:
        raise ValueError("Invalid nx value")
    if not isinstance(ny, int) or ny <= 0:
        raise ValueError("Invalid ny value")
    if not isinstance(xrange, list) or not isinstance(yrange, list):
        raise ValueError("Invalid xrange or yrange type")
    if len(xrange) != nx + 1 or len(yrange) != ny + 1:
        raise ValueError("Invalid xrange or yrange length")
    for i in range(1, len(xrange)):
        if xrange[i] <= xrange[i - 1]:
            raise ValueError("Invalid xrange order")
    for i in range(1, len(yrange)):
        if yrange[i] <= yrange[i - 1]:
            raise ValueError("Invalid yrange order")

    xrange_ptr = (ctypes.c_double * (nx + 1))(*xrange)
    yrange_ptr = (ctypes.c_double * (ny + 1))(*yrange)

    return gsl.gsl_histogram2d_calloc_range(nx, ny, xrange_ptr, yrange_ptr)

